 state.players.forEach((p,i)=>{if(i!==me())drawHero(c,px(p.x),pz(p.z),p.facing,p.hp>0?'#9cc7ff':'#7a7a7a',icon*.42);});const self=state.players[me()];drawHero(c,px(self.x),pz(self.z),self.facing,'#fff1b4',icon*.62);
