  if(key==='copy'){try{await navigator.clipboard.writeText(code);notice='Código copiado.';}catch{notice='Código da sala: '+code;}renderMenu();return;}if(key.startsWith('class-')){const i=NIGHT_CLASSES.findIndex(c=>c.id===classId);classId=NIGHT_CLASSES[(i+(key==='class-next'?1:NIGHT_CLASSES.length-1))%NIGHT_CLASSES.length].id;profile();return;}if(key==='ready'){const m=members.find(m=>m.id===self);if(m)m.ready=!m.ready;profile();return;}if(key==='start'){start();return;}if(key==='reconnect'){room?.reconnect();overlay='';renderPanel();return;}if(!state)return;
