  const warnings:Record<number,string>={1:'GARRAS · AFASTA-TE',2:'SALTO · SAI DO CÍRCULO',3:'MARÉ · APROXIMA-TE',4:'INVESTIDA · ESQUIVA PARA O LADO',5:'ECLIPSE · SAI DA ÁREA'};root.querySelector('.night-warning')!.textContent=p.hp<=0?'CAÍDO · um aliado pode reanimar-te':boss&&state.boss.stage===1?warnings[state.boss.attack]:boss&&state.boss.stage===4?'POSTURA QUEBRADA · CONTRA-ATACA!':state.phase==='explore'&&state.phaseTime<15?'O BOSS CHAMA · TELEPORTE EM '+Math.ceil(state.phaseTime)+'s':'';
  root.querySelector('.hunt-damage-flash')!.classList.toggle('active',p.hit>0);const power=root.querySelector<HTMLButtonElement>('.hunt-power')!,ult=root.querySelector<HTMLButtonElement>('.hunt-ultimate')!,potion=root.querySelector<HTMLButtonElement>('[data-night=potion]')!;power.disabled=p.powerCd>0||p.hp<=0;power.style.setProperty('--cd',Math.min(100,p.powerCd/12*100)+'%');power.querySelector('small')!.textContent=p.powerCd>0?Math.ceil(p.powerCd)+'s':p.spell==='class'?classFor(p.classId).power:p.spell==='garden'?'Jardim':p.spell==='ward'?'Escudo':'Meteoro';ult.disabled=p.energy<100||p.hp<=0;ult.style.setProperty('--cd',(100-p.energy)+'%');ult.querySelector('small')!.textContent=p.energy<100?Math.floor(p.energy)+'%':'Especial';root.querySelector('.hunt-stick')?.classList.toggle('dodge-ready',p.stamina>=28&&p.dodgeCd===0&&p.hp>0);potion.disabled=p.potionCd>0||p.potions===0||p.hp<=0;potion.querySelector('small')!.textContent=p.potionCd>0?Math.ceil(p.potionCd)+'s':'Poção '+p.potions;
  const interaction=root.querySelector<HTMLButtonElement>('.night-interact')!,portal=state.phase==='explore'&&NIGHT_PORTALS.some(v=>gap(v,p)<3),spring=state.phase==='explore'&&NIGHT_SPRINGS.some((v,i)=>gap(v,p)<3&&state!.springs[i]>0);const npc=['explore','sanctuary'].includes(state.phase)?nearbyNpc(p):undefined;const monument=state.phase==='explore'?nearbyMonument(p):undefined;interaction.hidden=!monument&&!npc&&!portal&&!spring&&state.phase!=='sanctuary';interaction.dataset.night=npc||monument?'interact':state.phase==='sanctuary'?'shop':'interact';interaction.textContent=npc?'Falar com '+npc.name:monument?'Examinar monumento':portal?'◇ Ativar / viajar':spring?'✚ Fonte de cura':'✦ Abrir santuário';
  // Quest tracker under the title during exploration, and a toast when one completes.
