  tracker.innerHTML=quests.map(q=>`<li class="${q.done?'done':''}">${skillIcon(questIcon[q.kind])}<span>${esc(q.title)}</span><b>${q.done?'✓':q.progress+'/'+q.goal}</b></li>`).join('');
  const doneKey=state.stage+':'+quests.map(q=>q.done?1:0).join('');if(questsDone&&doneKey!==questsDone&&doneKey.split(':')[0]===questsDone.split(':')[0]){const fresh=quests.find((q,i)=>q.done&&questsDone.split(':')[1][i]==='0');if(fresh){const toast=root.querySelector<HTMLElement>('.night-quest-toast')!;toast.innerHTML=`<small>MISSÃO CONCLUÍDA</small><strong>${esc(fresh.title)}</strong><span>+${fresh.gold} ouro${fresh.points?` · +${fresh.points} ${fresh.points>1?'pontos':'ponto'} de atributo · +1 poção`:''}</span>`;toast.hidden=false;toastUntil=now+3800;options.sound('heal');}}questsDone=doneKey;root.querySelector<HTMLElement>('.night-quest-toast')!.hidden=now>toastUntil;
