  for(const [selector,cd,label] of [['.night-defense',p.utilityCd,CLASS_SKILLS[p.classId].defense],['.night-control',p.hexCd,CLASS_SKILLS[p.classId].control]] as const){const b=root.querySelector<HTMLButtonElement>(selector)!;b.disabled=cd>0||p.hp<=0;b.style.setProperty('--cd',Math.min(100,cd/18*100)+'%');b.title=label;b.querySelector('small')!.textContent=cd>0?Math.ceil(cd)+'s':label;}
  const attributeButton=root.querySelector<HTMLButtonElement>('[data-night=attributes]')!;attributeButton.classList.toggle('has-points',p.points>0);attributeButton.innerHTML=`↑<small>${p.points?'+'+p.points+' pontos':'Atributos'}</small>`;const nextAttributeKey=JSON.stringify([p.points,p.attributes,p.level,Math.floor(p.xp),state.phase]);if(overlay==='attributes'&&nextAttributeKey!==attributeKey){attributeKey=nextAttributeKey;renderPanel();}
