  const nextCampaignKey=JSON.stringify([p.missions,p.talents,p.level,p.gold,state.cleared,state.stage,state.phase]);if(['npc','journal','talents'].includes(overlay)&&campaignKey!==nextCampaignKey){campaignKey=nextCampaignKey;renderPanel();}
  const nextShopKey=JSON.stringify([p.gold,p.upgrades,p.potions,p.ready,Math.ceil(state.phaseTime/5)]);if(overlay==='shop'&&nextShopKey!==shopKey){shopKey=nextShopKey;renderPanel();}root.querySelector('[data-night=run]')?.classList.toggle('active',runHeld);if(overlay==='map')drawMap(root.querySelector('.night-map-canvas')!);drawMinimap();
